// Fase 5h (Personalização 100%: botões, modais, painéis e formulários criados, ticket com assuntos + tudo da 5b a 5g) — PAINEL
// Uso: coloque este arquivo na pasta do projeto e rode:  node instalar-fase5h-painel.cjs
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const raiz = process.cwd();
if (!fs.existsSync(path.join(raiz, 'src', 'app')) || !fs.existsSync(path.join(raiz, 'scripts', 'gerar-template-bot.mjs'))) {
  console.error('❌ Rode dentro da pasta do PAINEL (onde ficam src/app e scripts/gerar-template-bot.mjs).');
  process.exit(1);
}
const arquivos = JSON.parse(zlib.gunzipSync(Buffer.from(DADOS(), 'base64')).toString('utf8'));
let n = 0;
for (const [rel, conteudo] of Object.entries(arquivos)) {
  const destino = path.join(raiz, ...rel.split('/'));
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  const existia = fs.existsSync(destino);
  fs.writeFileSync(destino, conteudo);
  console.log((existia ? '  atualizado  ' : '  criado      ') + rel);
  n++;
}

// tabelas novas no prisma/schema.prisma (só as que ainda não existem)
const schemaPath = path.join(raiz, 'prisma', 'schema.prisma');
const BLOCOS = {"BuilderPrice":"// Preços do \"Monte o seu bot\" (editados em /admin/loja/montador).\n// Sem linha aqui = usa o preço padrão de src/lib/builder/catalog.ts no painel.\nmodel BuilderPrice {\n  moduleId   String   @id // \"base\" ou o id do módulo (ex.: \"moderacao\")\n  priceCents Int\n  active     Boolean  @default(true) // false = módulo fora de venda\n  updatedAt  DateTime @updatedAt\n}","BuilderCombo":"// Combos do \"Monte o seu bot\" (desconto editado em /admin/loja/montador).\n// Os módulos de cada combo ficam em src/lib/builder/catalog.ts no painel.\nmodel BuilderCombo {\n  id          String   @id // ex.: \"seguranca\"\n  discountPct Int      // desconto em % sobre os módulos do combo\n  active      Boolean  @default(true)\n  updatedAt   DateTime @updatedAt\n}","StoreTester":"// Contas do Discord que compram na loja sem pagar (para testes). Editado em /admin/loja/testadores.\nmodel StoreTester {\n  userId    String   @id // ID do Discord\n  note      String   @default(\"\")\n  createdAt DateTime @default(now())\n}"};
if (fs.existsSync(schemaPath)) {
  let schema = fs.readFileSync(schemaPath, 'utf8');
  const novos = Object.keys(BLOCOS).filter((m) => !schema.includes('model ' + m + ' {'));
  if (novos.length) {
    schema = schema.replace(/\s*$/, '\n');
    for (const m of novos) schema += '\n' + BLOCOS[m] + '\n';
    fs.writeFileSync(schemaPath, schema);
    console.log('  ajustado    prisma/schema.prisma (' + novos.join(', ') + ')');
  } else console.log('  já tinha    prisma/schema.prisma');
} else console.log('  ⚠️ não achei prisma/schema.prisma');
console.log('\n✅ ' + n + ' arquivo(s) prontos. Pode apagar o instalar-fase5h-painel.cjs.');
function DADOS() { return ''; }
